const crypto=require('crypto');
const secret=String($env.DROP_RATE_AUTOMATION_COMMAND_SECRET||'').trim();
const url=String($env.DROP_RATE_API_AUTOMATION_CONTROL_URL||'').trim();
if(secret.length<32) throw new Error('legacy_release_command_secret_unavailable');
if(!/\/api\/v1\/automation\/control\/receipt$/.test(url)) throw new Error('legacy_release_control_url_invalid');
const executionId=String($execution.id||'').slice(0,120);
if(!executionId) throw new Error('legacy_release_execution_id_missing');
const body=JSON.stringify({schema_version:1,action:'CHECK_LEGACY_RELEASE_SOURCE',source:'tcgdex',execution_id:executionId,occurred_at:new Date().toISOString()});
const timestamp=String(Math.floor(Date.now()/1000));
const signature='sha256='+crypto.createHmac('sha256',secret).update(timestamp+'.'+body,'utf8').digest('hex');
return [{json:{url:url.replace(/\/control\/receipt$/,'/commands/catalogue/check-legacy-release-source'),body,timestamp,signature}}];

const reply=$input.first().json||{};
if(!Number.isInteger(Number(reply.statusCode))||Number(reply.statusCode)<200||Number(reply.statusCode)>=300) throw new Error('legacy_release_http_'+reply.statusCode);
const r=reply.body||{};
if(r.accepted!==true || r.source!=='tcgdex' || !r.execution_id || !r.game) throw new Error('legacy_release_receipt_invalid');
if(r.metadata_only!==true||r.artwork_published!==false||r.shopify_updated!==false||r.ownership_or_price_changed!==false) throw new Error('legacy_release_scope_overreach');
if(!Number.isInteger(r.new_sets)||r.new_sets<0) throw new Error('legacy_release_new_sets_invalid');
if(!['CURRENT','ALREADY_RUNNING','VERIFIED_SOURCE_REFRESH','DEFERRED_CAPACITY','DISABLED_BY_POLICY','DEFERRED_RIOT_APPROVAL'].includes(r.status)) throw new Error('legacy_release_status_unverified');
if(r.status==='DEFERRED_RIOT_APPROVAL' && (r.source!=='riftbound_riot' || r.reason!=='OFFICIAL_APP_KEY_OR_LICENSE_REQUIRED')) throw new Error('riot_approval_state_invalid');
if(r.status==='DEFERRED_CAPACITY'&&!r.reason) throw new Error('legacy_capacity_receipt_missing');
if(r.status==='VERIFIED_SOURCE_REFRESH'&&(!Number.isInteger(r.sets_checked)||!Number.isInteger(r.records_checked))) throw new Error('legacy_refresh_counts_unverified');
return [{json:{source:r.source,game:r.game,status:r.status,new_sets:r.new_sets,reason:r.reason||null,metadata_only:true,requires_action:r.status==='DEFERRED_RIOT_APPROVAL'||r.status==='DEFERRED_CAPACITY'}}];
